import cupy as cp


def low_rank(A, k):
    n = A.shape[1]
    k = int(min(k, min(A.shape)))
    if k <= 0:
        return cp.zeros_like(A)
    Q, R = cp.linalg.qr(A, mode="reduced")          # Q: (m, n), R: (n, n)
    U, s, Vt = cp.linalg.svd(R, full_matrices=False)
    Uk = Q @ (U[:, :k] * s[:k])                      # (m, k)
    return Uk @ Vt[:k, :]

import cupy as cp


def low_rank(A, k):
    k = int(min(k, min(A.shape)))
    if k <= 0:
        return cp.zeros_like(A)
    # A = Q R, with R small (n x n); SVD of R gives the SVD of A
    Q, R = cp.linalg.qr(A, mode="reduced")
    U, s, Vh = cp.linalg.svd(R, full_matrices=False)
    Uk = Q @ U[:, :k]
    return (Uk * s[:k]) @ Vh[:k, :]

import cupy as cp


def low_rank(A, k):
    n = A.shape[1]
    if k <= 0:
        return cp.zeros_like(A)
    k = min(k, n, A.shape[0])
    # QR first: the SVD then runs on the small n x n factor R
    Q, R = cp.linalg.qr(A, mode='reduced')
    U, s, Vh = cp.linalg.svd(R, full_matrices=False)
    Uk = U[:, :k] * s[:k]          # (n, k)
    return Q @ (Uk @ Vh[:k, :])

